const Image *GameWindowManager::winFindImage(const char *name)
{
	if (TheMappedImageCollection != 0)
	{
		AsciiString str(name);
		const Image *img = TheMappedImageCollection->findImageByName(str);
		return img;
	}
	else
		return 0;
}

